// Thin NCNN wrapper loaded by the Node SDK. No Python.
#include <cstring>
#include "net.h"

struct DuixNet {
    ncnn::Net net;
};

static void copy_packed(ncnn::Mat& dst, const float* src, int w, int h, int c) {
    const size_t plane = (size_t)w * h;
    if (dst.cstep == plane) {
        std::memcpy(dst.data, src, plane * c * sizeof(float));
        return;
    }
    for (int ch = 0; ch < c; ch++) {
        std::memcpy(dst.channel(ch), src + plane * ch, plane * sizeof(float));
    }
}

extern "C" __declspec(dllexport)
DuixNet* duix_open(const char* param, const char* model, int binary) {
    DuixNet* h = new DuixNet();
    h->net.opt.use_vulkan_compute = false;
    h->net.opt.num_threads = 2;
    h->net.opt.use_fp16_packed = false;
    h->net.opt.use_fp16_storage = false;
    h->net.opt.use_fp16_arithmetic = false;
    int pret = binary ? h->net.load_param_bin(param) : h->net.load_param(param);
    int mret = h->net.load_model(model);
    if (pret != 0 || mret != 0) {
        delete h;
        return 0;
    }
    return h;
}

extern "C" __declspec(dllexport)
int duix_infer(DuixNet* h, const float* face, const float* audio,
               int audio_index, int face_index, int output_index,
               unsigned char* rgb) {
    if (!h || !face || !audio || !rgb) return -1;
    ncnn::Mat in_audio(256, 20, 1);
    ncnn::Mat in_face(160, 160, 6);
    copy_packed(in_audio, audio, 256, 20, 1);
    copy_packed(in_face, face, 160, 160, 6);

    ncnn::Extractor ex = h->net.create_extractor();
    if (ex.input(audio_index, in_audio) != 0) return -2;
    if (ex.input(face_index, in_face) != 0) return -3;
    ncnn::Mat out;
    if (ex.extract(output_index, out) != 0) return -4;
    if (out.w != 160 || out.h != 160 || out.c != 3) return -5;

    for (int c = 0; c < 3; c++) {
        const float* ch = out.channel(c);
        for (int i = 0; i < 160 * 160; i++) {
            float v = (ch[i] + 1.f) * 127.5f;
            int q = (int)(v + 0.5f);
            if (q < 0) q = 0;
            if (q > 255) q = 255;
            rgb[i * 3 + c] = (unsigned char)q;
        }
    }
    return 0;
}

extern "C" __declspec(dllexport)
void duix_close(DuixNet* h) {
    delete h;
}
